from pyspark.sql import functions as F, Window
from decimal import Decimal

def run(spark, tables):
    claims = tables['claims']
    policy = tables['policy']

    # Step 1: Join policy and claims tables
    policy_claims = policy.join(claims, policy['IDpol'] == claims['IDpol'], 'left')

    # Step 2: Calculate loss summary per region
    region_loss = policy_claims.groupBy('Region') \
        .agg(
            F.count('ClaimAmount').alias('ClaimCount'),
            F.sum('ClaimAmount').alias('TotalLoss'),
            F.avg('ClaimAmount').alias('AvgLoss')
        )

    return region_loss
